;; If most of a -> is unconditional but one step is conditional, cond-> is useful:

(-> {}
    (assoc :foo "foo")
    (cond-> false
      (assoc :truthy true))
    (assoc :bar "bar"))
;; => {:foo "foo", :bar "bar"}


(-> {}
    (assoc :foo "foo")
    (cond-> true              ; this is the only change from above
      (assoc :truthy true))
    (assoc :bar "bar"))
;; => {:foo "foo", :truthy true, :bar "bar"}

