;; Use merge-with and merge to merge values that are one level deep maps.

(merge-with merge {:x {:y 1}} {:x {:z 2}})
;;=> {:x {:z 2, :y 1}}

;; Deeper maps are not merged:
(merge-with merge {:x {:y {:a 1}}} {:x {:y {:b 2}}})
;;=>{:x {:y {:b 2}}}

