;; select elements using reduce-kv & filter
(defn multi-pred [coll m] 
  (reduce-kv 
    (fn [erg k v] (filter #(= v (k %)) erg)) coll m)  )

;; two "preds"
(multi-pred people {:gender "male", :age-group "senior"})
;; => ({:gender "male", :age-group "senior", :origin "Estonia", :prename "Rasmus"} {:gender "male", :age-group "senior", :origin "Germany", :prename "Uwe"})

