(update-vals {:a 1, :b 2} inc)
;; => {:a 2, :b 3}

;; To replace each map with its value for a specific key…
(update-vals {:a {:x 7, :y 100}, :b {:x 8, :y 150}, :c {:x 9, :y 200}} :x)
;; => {:a 7, :b 8, :c 9}

;; To dissoc a kv pair from each map…
(update-vals {:a {:x 7, :y 100}, :b {:x 8, :y 150}, :c {:x 9, :y 200}}
             #(dissoc % :x))
;; => {:a {:y 100}, :b {:y 150}, :c {:y 200}}

